/* eslint-disable space-in-parens */

import zeros = require( '@stdlib/ndarray/zeros' );
import scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
import joinBetween = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});

	joinBetween( x, sep ); // $ExpectType OutputArray<string>
	joinBetween( x, sep, {} ); // $ExpectType OutputArray<string>
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});

	joinBetween( '5', sep ); // $ExpectError
	joinBetween( 5, sep ); // $ExpectError
	joinBetween( true, sep ); // $ExpectError
	joinBetween( false, sep ); // $ExpectError
	joinBetween( null, sep ); // $ExpectError
	joinBetween( void 0, sep ); // $ExpectError
	joinBetween( {}, sep ); // $ExpectError
	joinBetween( ( x: number ): number => x, sep ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});

	joinBetween( x, '5' ); // $ExpectError
	joinBetween( x, 5 ); // $ExpectError
	joinBetween( x, true ); // $ExpectError
	joinBetween( x, false ); // $ExpectError
	joinBetween( x, null ); // $ExpectError
	joinBetween( x, void 0 ); // $ExpectError
	joinBetween( x, {} ); // $ExpectError
	joinBetween( x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});

	joinBetween( x, sep, '5' ); // $ExpectError
	joinBetween( x, sep, true ); // $ExpectError
	joinBetween( x, sep, false ); // $ExpectError
	joinBetween( x, sep, [] ); // $ExpectError
	joinBetween( x, sep, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid `dims` option...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});

	joinBetween( x, sep, { 'dims': '5' } ); // $ExpectError
	joinBetween( x, sep, { 'dims': 5 } ); // $ExpectError
	joinBetween( x, sep, { 'dims': true } ); // $ExpectError
	joinBetween( x, sep, { 'dims': false } ); // $ExpectError
	joinBetween( x, sep, { 'dims': null } ); // $ExpectError
	joinBetween( x, sep, { 'dims': {} } ); // $ExpectError
	joinBetween( x, sep, { 'dims': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid `keepdims` option...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});

	joinBetween( x, sep, { 'keepdims': '5' } ); // $ExpectError
	joinBetween( x, sep, { 'keepdims': 5 } ); // $ExpectError
	joinBetween( x, sep, { 'keepdims': null } ); // $ExpectError
	joinBetween( x, sep, { 'keepdims': {} } ); // $ExpectError
	joinBetween( x, sep, { 'keepdims': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});

	joinBetween(); // $ExpectError
	joinBetween( x ); // $ExpectError
	joinBetween( x, sep, {}, {} ); // $ExpectError
}

// Attached to the function is an `assign` method which returns an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});
	const y = scalar2ndarray( '', {
		'dtype': 'generic'
	});

	joinBetween.assign( x, sep, y ); // $ExpectType genericndarray<string>
	joinBetween.assign( x, sep, y, {} ); // $ExpectType genericndarray<string>
}

// The compiler throws an error if the `assign` method is provided a first argument which is not an ndarray...
{
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});
	const y = scalar2ndarray( '' );

	joinBetween.assign( '5', sep, y ); // $ExpectError
	joinBetween.assign( 5, sep, y ); // $ExpectError
	joinBetween.assign( true, sep, y ); // $ExpectError
	joinBetween.assign( false, sep, y ); // $ExpectError
	joinBetween.assign( null, sep, y ); // $ExpectError
	joinBetween.assign( void 0, sep, y ); // $ExpectError
	joinBetween.assign( {}, sep, y ); // $ExpectError
	joinBetween.assign( ( x: number ): number => x, sep, y ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a second argument which is not an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const y = scalar2ndarray( '' );

	joinBetween.assign( x, '5', y ); // $ExpectError
	joinBetween.assign( x, 5, y ); // $ExpectError
	joinBetween.assign( x, true, y ); // $ExpectError
	joinBetween.assign( x, false, y ); // $ExpectError
	joinBetween.assign( x, null, y ); // $ExpectError
	joinBetween.assign( x, void 0, y ); // $ExpectError
	joinBetween.assign( x, {}, y ); // $ExpectError
	joinBetween.assign( x, ( x: number ): number => x, y ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided a third argument which is not an ndarray...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});

	joinBetween.assign( x, sep, '5' ); // $ExpectError
	joinBetween.assign( x, sep, 5 ); // $ExpectError
	joinBetween.assign( x, sep, true ); // $ExpectError
	joinBetween.assign( x, sep, false ); // $ExpectError
	joinBetween.assign( x, sep, null ); // $ExpectError
	joinBetween.assign( x, sep, void 0 ); // $ExpectError
	joinBetween.assign( x, sep, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided an options argument which is not an object...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});
	const y = scalar2ndarray( '' );

	joinBetween.assign( x, sep, y, '5' ); // $ExpectError
	joinBetween.assign( x, sep, y, true ); // $ExpectError
	joinBetween.assign( x, sep, y, false ); // $ExpectError
	joinBetween.assign( x, sep, y, null ); // $ExpectError
	joinBetween.assign( x, sep, y, [] ); // $ExpectError
	joinBetween.assign( x, sep, y, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided an invalid `dims` option...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});
	const y = scalar2ndarray( '' );

	joinBetween.assign( x, sep, y, { 'dims': '5' } ); // $ExpectError
	joinBetween.assign( x, sep, y, { 'dims': 5 } ); // $ExpectError
	joinBetween.assign( x, sep, y, { 'dims': true } ); // $ExpectError
	joinBetween.assign( x, sep, y, { 'dims': false } ); // $ExpectError
	joinBetween.assign( x, sep, y, { 'dims': null } ); // $ExpectError
	joinBetween.assign( x, sep, y, { 'dims': {} } ); // $ExpectError
	joinBetween.assign( x, sep, y, { 'dims': ( x: number ): number => x } ); // $ExpectError
}

// The compiler throws an error if the `assign` method is provided an unsupported number of arguments...
{
	const x = zeros( [ 2, 2 ], {
		'dtype': 'float64'
	});
	const sep = scalar2ndarray( ',', {
		'dtype': 'generic'
	});
	const y = scalar2ndarray( '' );

	joinBetween.assign(); // $ExpectError
	joinBetween.assign( x ); // $ExpectError
	joinBetween.assign( x, sep ); // $ExpectError
	joinBetween.assign( x, sep, y, {}, {} ); // $ExpectError
}
